[InitializeOnLoad] public static class InvestigationControllerRouteChecks {
 const string K="ConRoi.FlowController",Scene="Assets/ConRoi/Modules/Gameplay/Scenes/Gameplay_ThuNghiem.unity";
 static double next;static IEnumerator run;static int frame=-1,fail;static GameObject root;static InvestigationSession s;static Keyboard keyboard;static EditorWindow view;static JArray rows;static string output;
 static InvestigationControllerRouteChecks(){EditorApplication.update+=Tick;}
 static string Arg(string k){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,k);return i>=0&&i+1<a.Length?a[i+1]:"";}
 public static void RunBatch(){if(!Application.isBatchMode||Application.unityVersion!="6000.6.2f1"||EditorApplication.isPlayingOrWillChangePlaymode)throw new InvalidOperationException("Explicit batch only; no desktop input");if(Directory.Exists(Arg("--investigation-save-dir"))||!Path.IsPathRooted(Arg("--investigation-save-dir")))throw new InvalidOperationException("New private profile required");output=Arg("--flow-ui-output");Directory.CreateDirectory(output);SessionState.SetString(K+".out",output);EditorSceneManager.OpenScene(Scene,OpenSceneMode.Single);SessionState.SetString(K,"pending");EditorApplication.EnterPlaymode();}
 static void Check(string name,bool pass){rows.Add(new JObject{["name"]=name,["pass"]=pass,["page"]=s.Page,["message"]=s.Message});if(!pass){var tex=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Path.Combine(output,"failure.png"),tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);File.WriteAllText(Path.Combine(output,"failure-data.json"),JsonUtility.ToJson(s.data,true));fail++;throw new Exception("UI precondition failed: "+name);}}
 static void Click(float x,float y,float offset=0){var point=new Vector2(x*Screen.width/1200f/EditorGUIUtility.pixelsPerPoint,y*Screen.height/800f/EditorGUIUtility.pixelsPerPoint+22+offset);foreach(var type in new[]{EventType.MouseDown,EventType.MouseUp})view.SendEvent(new Event{type=type,button=0,mousePosition=point});view.Repaint();}
 static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;string phase=SessionState.GetString(K,"");if(phase=="finished"&&!EditorApplication.isPlayingOrWillChangePlaymode){SessionState.SetString(K,"");EditorApplication.Exit(SessionState.GetInt(K+".exit",2));return;}if(!EditorApplication.isPlaying)return;
 try{if(phase=="pending"){output=SessionState.GetString(K+".out","");rows=new JArray();s=TrialPlaybackContextChecks.BuildEnvironment(out root);foreach(var spec in new[]{new{id="phone",x=4f},new{id="ha",x=6f}}){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name="Controller interaction "+spec.id;go.transform.SetParent(root.transform);go.transform.position=new Vector3(spec.x,1.6f,2.7f);go.transform.localScale=new Vector3(.5f,.5f,.1f);go.AddComponent<InvestigationInteractable>().evidenceId=spec.id;}keyboard=InputSystem.AddDevice<Keyboard>("PrivateFlowKeyboard");view=EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView"));view.position=new Rect(0,0,1280,900);view.Repaint();File.WriteAllText(Path.Combine(output,"event-apis.txt"),string.Join("\n",typeof(UnityEditorInternal.InternalEditorUtility).GetMethods(BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).Where(m=>m.Name.Contains("SendEvent")).Select(m=>m.ToString())));run=Route();SessionState.SetString(K,"running");next=EditorApplication.timeSinceStartup+.5;return;}if(phase!="running"||EditorApplication.timeSinceStartup<next||Time.frameCount==frame)return;frame=Time.frameCount;next=EditorApplication.timeSinceStartup+.15;if(!Step())Finish();}catch(Exception e){rows.Add(new JObject{["exception"]=e.ToString(),["pass"]=false});fail++;Finish();}}
 static readonly Stack<IEnumerator> tasks=new Stack<IEnumerator>();
 static bool Step(){if(tasks.Count==0)tasks.Push(run);while(tasks.Count>0){var t=tasks.Peek();if(!t.MoveNext()){tasks.Pop();continue;}if(t.Current is IEnumerator nested){tasks.Push(nested);continue;}return true;}return false;}
 static void Finish(){while(tasks.Count>0){var pendingTask=tasks.Pop();try{(pendingTask as IDisposable)?.Dispose();}catch(Exception cleanup){rows.Add(new JObject{["cleanup_exception"]=cleanup.ToString(),["pass"]=false});fail++;}}if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);if(root)UnityEngine.Object.DestroyImmediate(root);Time.timeScale=1;File.WriteAllText(Path.Combine(output,"results.json"),new JObject{["source"]=Arg("--flow-source"),["kind"]="UNITY_TARGETED_IMGUI_AND_VIRTUAL_KEYBOARD_NOT_WINDOWS_NOT_NATURAL",["scene"]=Scene,["width"]=Screen.width,["height"]=Screen.height,["failures"]=fail,["checks"]=rows}.ToString());SessionState.SetInt(K+".exit",fail==0?0:1);SessionState.SetString(K,"finished");EditorApplication.ExitPlaymode();}
 static IEnumerator Key(Key key,int frames=1){InputSystem.QueueStateEvent(keyboard,new KeyboardState(key));for(int i=0;i<frames;i++)yield return null;InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return null;}
 static IEnumerator Go(float x){for(int i=0;i<100;i++){float delta=x-s.movement.transform.position.x;if(Mathf.Abs(delta)<.18f)yield break;yield return Key(delta>0?UnityEngine.InputSystem.Key.D:UnityEngine.InputSystem.Key.A);}throw new Exception("Controller cannot reach target x "+x);}
 static IEnumerator Shot(string name){ScreenCapture.CaptureScreenshot(Path.Combine(output,name+".png"));File.WriteAllText(Path.Combine(output,name+".json"),new JObject{["page"]=s.Page,["data"]=JObject.Parse(JsonUtility.ToJson(s.data)),["message"]=s.Message,["transcript"]=s.Has("clip")?s.EvidenceTranscript("clip"):"",["position"]=JObject.Parse(JsonUtility.ToJson(s.movement.transform.position)),["confirmed"]=s.ConclusionsConfirmed}.ToString());yield return null;}
 static readonly Dictionary<string,float> recordYs=new Dictionary<string,float>();
 static IEnumerator Record(string id){if(recordYs.ContainsKey(id)){Click(865,recordYs[id]);yield return null;}else for(float y=220;y<=450;y+=12){Click(865,y);yield return null;if(s.Record(id).observations.Count>0){recordYs[id]=y;break;}}Check(id+"_UI_record",s.Record(id).observations.Count>0);}
 static IEnumerator DossierPage(string page){for(float y=125;y<285;y+=10){Click(130,y);yield return null;if(s.Page==page)yield break;if(s.Page!="dossier"){yield return Key(UnityEngine.InputSystem.Key.R);yield return Key(UnityEngine.InputSystem.Key.P);}}throw new Exception("Cannot locate dossier navigation "+page);}
 static IEnumerator ClipRecord(){for(float y=590;y<750&&s.Page=="clip";y+=8){Click(844,y);yield return null;}Check("clip_record_button_opens_inspect",s.Page=="inspect");}
 static IEnumerator OpenConclusion(){yield return Key(UnityEngine.InputSystem.Key.P);Check("P_dossier_for_conclusion",s.Page=="dossier");for(float y=170;y<=230&&s.Page=="dossier";y+=10){Click(730,y);yield return null;}Check("conclusion_UI_open",s.Page=="conclusions");}
 static IEnumerator CommitConclusion(){float confirmY=0;for(float y=450;y<680&&!s.ConclusionsConfirmed;y+=10){Click(730,y);yield return null;if(s.ConclusionsConfirmed)confirmY=y;}Check("UI_neutral_confirmation",s.ConclusionsConfirmed);for(float y=confirmY+44;y<confirmY+110&&!s.data.finalized;y+=8){Click(730,y);yield return null;}Check("UI_finalization_saves",s.data.finalized&&File.Exists(s.BeforeConclusionSavePath)&&File.Exists(s.SavePath));}

 static float confirmationY;
 static IEnumerator ConfirmConclusionUI(){confirmationY=0;for(float y=450;y<680&&!s.ConclusionsConfirmed;y+=10){Click(730,y);yield return null;if(s.ConclusionsConfirmed)confirmationY=y;}Check("closure_UI_confirmation",s.ConclusionsConfirmed&&confirmationY>0);}
 static IEnumerator SaveConclusionUI(bool success){for(float y=confirmationY+44;y<confirmationY+110;y+=8){Click(730,y);yield return null;if(success?s.data.finalized:s.Message.StartsWith("Không chốt"))break;}Check(success?"closure_UI_commit_success":"closure_UI_commit_rejected",success?s.data.finalized&&s.Message.StartsWith("Đã lưu"):!s.data.finalized&&s.Message.StartsWith("Không chốt"));}
