  yield return ConfirmConclusionUI();Click(275,414);yield return null;Check("UI_ground_change_clears_confirmation",s.data.conclusions[0].grounds.Contains("slide")&&!s.ConclusionsConfirmed);yield return ConfirmConclusionUI();Click(275,414);yield return null;Check("UI_ground_restore_does_not_restore_confirmation",s.data.conclusions[0].grounds.Count==0&&!s.ConclusionsConfirmed);
  yield return ConfirmConclusionUI();Click(500,372);foreach(var type in new[]{EventType.KeyDown,EventType.KeyUp})view.SendEvent(new Event{type=type,keyCode=KeyCode.X,character='x'});yield return null;Check("UI_claim_change_clears_confirmation",!string.IsNullOrEmpty(s.data.conclusions[0].claim)&&!s.ConclusionsConfirmed);
  yield return ConfirmConclusionUI();string state=JsonUtility.ToJson(s.data);byte[] good=File.ReadAllBytes(s.SavePath);string block=s.BeforeConclusionSavePath+".tmp";Directory.CreateDirectory(block);
  try{yield return SaveConclusionUI(false);}finally{Directory.Move(block,Path.Combine(output,"UI-blocked-temp-preserved"));}
  Check("UI_checkpoint_failure_state_and_bytes_preserved",JsonUtility.ToJson(s.data)==state&&good.SequenceEqual(File.ReadAllBytes(s.SavePath)));yield return SaveConclusionUI(true);
  Click(950,255);yield return null;Check("UI_edit_after_commit_requires_reconfirmation",s.data.conclusions[0].choice==1&&!s.data.finalized&&!s.ConclusionsConfirmed);yield return ConfirmConclusionUI();state=JsonUtility.ToJson(s.data);good=File.ReadAllBytes(s.SavePath);
  using(var held=new FileStream(s.SavePath,FileMode.Open,FileAccess.Read,FileShare.None)){yield return SaveConclusionUI(false);}
  Check("UI_target_failure_state_and_bytes_preserved",JsonUtility.ToJson(s.data)==state&&good.SequenceEqual(File.ReadAllBytes(s.SavePath)));yield return SaveConclusionUI(true);yield return Key(UnityEngine.InputSystem.Key.F6);Check("UI_recovery_load_preserves_latest_choice",s.data.finalized&&s.data.conclusions[0].choice==1&&!s.ConclusionsConfirmed);
 }
