  for(int i=0;i<10;i++){view.Repaint();yield return null;}foreach(float offset in new[]{0f,22f,-22f}){if(s.Page!="intro")break;Click(600,390,offset);yield return null;}Check("intro_UI_start",s.Page==""&&s.data.introAccepted&&!s.data.tutorialSkipped&&s.data.evidence.Count==0);
