  yield return Go(6);yield return Key(UnityEngine.InputSystem.Key.E);Check("E_Ha_returns_existing_letter_data",s.data.visitedHa&&s.Has("letter")&&s.Has("receipt")&&s.Has("draft")&&!s.Has("decoded"));yield return Key(UnityEngine.InputSystem.Key.R);
